  const returnedAnimalIds = new Set(here.map((x) => x.animalId));
  const returnedKinds = {};
  for (const x of here) {
    const kind = d.animal.get(x.animalId)?.kind;
    if (kind) returnedKinds[kind] = (returnedKinds[kind] || 0) + 1;
  }
  const placements = needPlaced ? (await byWorld(t2.Placement, wid)).filter((p) => p.area === biomeId) : [];
  const terrain = needWater ? (await byWorld(t2.TerrainTile, wid)).filter((tt) => tt.area === biomeId) : [];
